  "livequiz": {
    "FormPhone.form.yaml": "formatVersion: 1\nproperties:\n  Caption: LiveQuiz - 폰\n  Width: 360\n  Height: 480\ncontrols:\n  - name: lblStep\n    type: Label\n    properties:\n      Caption: 방 코드와 별명을 넣고 \"들어가기\"를 누르세요.\n      Left: 16\n      Top: 12\n      Width: 328\n      Height: 40\n  - name: txtCode\n    type: TextBox\n    properties:\n      Left: 16\n      Top: 56\n      Width: 120\n  - name: txtNickname\n    type: TextBox\n    properties:\n      Left: 144\n      Top: 56\n      Width: 200\n  - name: btnJoin\n    type: Button\n    properties:\n      Caption: 들어가기\n      Left: 16\n      Top: 96\n      Width: 328\n  - name: lblQuestion\n    type: Label\n    properties:\n      Left: 16\n      Top: 144\n      Width: 328\n      Height: 40\n  - name: btnChoice0\n    type: Button\n    properties:\n      Left: 16\n      Top: 192\n      Width: 328\n      Height: 40\n      Caption: \"1\"\n      Tag: \"0\"\n  - name: btnChoice1\n    type: Button\n    properties:\n      Left: 16\n      Top: 240\n      Width: 328\n      Height: 40\n      Caption: \"2\"\n      Tag: \"1\"\n  - name: btnChoice2\n    type: Button\n    properties:\n      Left: 16\n      Top: 288\n      Width: 328\n      Height: 40\n      Caption: \"3\"\n      Tag: \"2\"\n  - name: btnChoice3\n    type: Button\n    properties:\n      Left: 16\n      Top: 336\n      Width: 328\n      Height: 40\n      Caption: \"4\"\n      Tag: \"3\"\n  - name: lblResult\n    type: Label\n    properties:\n      Left: 16\n      Top: 392\n      Width: 328\n  - name: lblRank\n    type: Label\n    properties:\n      Left: 16\n      Top: 420\n      Width: 328\n  - name: rmQuiz\n    type: Room\n",
    "FormPhone.gbas": "' 폰 쪽: TV가 보여 주는 방 코드로 들어가, 문제가 오면 보기 버튼으로 답합니다.\n' 답은 TV에게만 보냅니다(SendTo). 다른 폰은 내 답을 보지 못합니다.\n\nDim host As String          ' TV의 멤버 ID: 문제와 함께 옵니다\nDim questionNo As Integer\n\nSub Form_Load()\n    ShowChoices(False)\nEnd Sub\n\n' 방 코드는 대문자로: 폰의 자판이 소문자를 넣어도 맞게.\nSub txtCode_Changed()\n    Dim upper As String = txtCode.Text.ToUpper()\n    If upper <> txtCode.Text Then txtCode.Text = upper\nEnd Sub\n\nSub btnJoin_Click()\n    If txtNickname.Text.Trim() = \"\" Then\n        MsgBox(\"별명을 넣어 주세요.\")\n        Exit Sub\n    End If\n    Try\n        ' 방에 들어갈 때까지 기다립니다. 없는 방이면 오류가 납니다.\n        rmQuiz.Join(txtCode.Text, txtNickname.Text)\n    Catch ex As Exception\n        MsgBox(ex.Message)\n        Exit Sub\n    End Try\n    lblStep.Caption = txtNickname.Text & \" 님, 들어왔습니다. 문제를 기다리세요.\"\n    ' 들어온 뒤에는 코드와 별명을 바꾸지 못하게 합니다.\n    btnJoin.Caption = \"방 \" & rmQuiz.Code\n    btnJoin.Enabled = False\n    txtCode.Enabled = False\n    txtNickname.Enabled = False\nEnd Sub\n\nSub rmQuiz_Message(e As RoomEventArgs)\n    Dim m As Json = e.Json\n    Select Case m(\"kind\").AsString\n        Case \"question\"\n            host = m(\"host\").AsString\n            questionNo = m(\"no\").AsInteger\n            lblQuestion.Caption = questionNo & \". \" & m(\"text\").AsString\n            Dim choices As Json = m(\"choices\")\n            btnChoice0.Caption = \"1) \" & choices(0).AsString\n            btnChoice1.Caption = \"2) \" & choices(1).AsString\n            btnChoice2.Caption = \"3) \" & choices(2).AsString\n            btnChoice3.Caption = \"4) \" & choices(3).AsString\n            ShowChoices(True)\n            lblResult.Caption = m(\"seconds\").AsInteger & \"초 안에 고르세요!\"\n        Case \"result\"\n            If m(\"correct\").AsBoolean Then\n                lblResult.Caption = \"정답! 지금 \" & m(\"score\").AsInteger & \"점\"\n            Else\n                lblResult.Caption = \"아쉽네요. 지금 \" & m(\"score\").AsInteger & \"점\"\n            End If\n        Case \"score\"\n            Dim board As Json = m(\"board\")\n            For i As Integer = 0 To board.Count - 1\n                If board(i)(\"member\").AsString = rmQuiz.Me Then\n                    lblRank.Caption = \"내 순위: \" & (i + 1) & \" / \" & board.Count\n                End If\n            Next\n            ShowChoices(False)\n        Case \"end\"\n            lblStep.Caption = \"끝났습니다. 고맙습니다!\"\n            ShowChoices(False)\n    End Select\nEnd Sub\n\nSub Choice_Click(sender As Button) Handles btnChoice0.Click, btnChoice1.Click, btnChoice2.Click, btnChoice3.Click\n    Dim chosen As String = sender.Caption\n    Dim answer As New Json\n    answer(\"kind\") = \"answer\"\n    answer(\"no\") = questionNo\n    answer(\"choice\") = CInt(sender.Tag)\n    rmQuiz.SendTo(host, answer.Text)\n    ShowChoices(False)\n    lblResult.Caption = \"답을 보냈습니다: \" & chosen\nEnd Sub\n\nSub rmQuiz_Closed(e As RoomEventArgs)\n    ShowChoices(False)\n    lblStep.Caption = \"방이 끝났습니다(\" & e.Reason & \").\"\nEnd Sub\n\n' 고를 수 없을 때는 보기 버튼을 끄고 번호만 남깁니다. 문제가 오면 번호와\n' 보기를 함께 보입니다: TV가 멀거나 작아도 폰에서 읽고 고를 수 있게.\nSub ShowChoices(shown As Boolean)\n    btnChoice0.Enabled = shown\n    btnChoice1.Enabled = shown\n    btnChoice2.Enabled = shown\n    btnChoice3.Enabled = shown\n    If shown Then Exit Sub\n    btnChoice0.Caption = \"1\"\n    btnChoice1.Caption = \"2\"\n    btnChoice2.Caption = \"3\"\n    btnChoice3.Caption = \"4\"\nEnd Sub\n",
    "FormStart.form.yaml": "formatVersion: 1\nproperties:\n  Caption: LiveQuiz\n  Width: 360\n  Height: 220\ncontrols:\n  - name: lblTitle\n    type: Label\n    properties:\n      Caption: 실시간 퀴즈. TV(또는 교실 화면)에서 방을 만들고, 폰으로 들어와 함께 풉니다.\n      Left: 16\n      Top: 16\n      Width: 328\n      Height: 48\n  - name: btnTV\n    type: Button\n    properties:\n      Caption: TV로 진행\n      Left: 16\n      Top: 80\n      Width: 328\n      Height: 48\n  - name: btnPhone\n    type: Button\n    properties:\n      Caption: 폰으로 참여\n      Left: 16\n      Top: 144\n      Width: 328\n      Height: 48\n",
    "FormStart.gbas": "' 실시간 퀴즈 LiveQuiz (docs/LANGUAGE.md 11.12): 한 프로젝트를 TV와 폰이\n' 함께 씁니다. TV 쪽은 Room으로 방을 만들어 코드를 보여 주고 문제를 내며,\n' 폰 쪽은 그 코드로 들어와 답을 보냅니다. 빨리 맞힐수록 점수가 많고,\n' TV에는 점수만큼 캐릭터가 달려 나갑니다.\n'\n' 중계 서버: Room.Server가 비어 있으면 데스크톱 IDE가 이 컴퓨터에 중계\n' 서버를 켭니다. 폰에서 해 보려면 디버그 메뉴의 \"같은 네트워크의 기기 허용\"을\n' 켭니다. 앱으로 내보낼 때는 두 폼의 rmQuiz.Server에 자기 중계 서버 주소\n' (wss://relay.example.com/room 같은)를 넣습니다(docs/RELAY_SERVER.ko.md).\n\nSub btnTV_Click()\n    FormTV.Show()\n    Me.Hide()\nEnd Sub\n\nSub btnPhone_Click()\n    FormPhone.Show()\n    Me.Hide()\nEnd Sub\n",
    "FormTV.form.yaml": "formatVersion: 1\nproperties:\n  Caption: LiveQuiz - TV\n  Width: 640\n  Height: 480\ncontrols:\n  - name: lblCode\n    type: Label\n    properties:\n      Caption: 방을 만드는 중…\n      Left: 16\n      Top: 4\n      Width: 440\n      Height: 36\n      FontSize: 24.0\n      FontBold: true\n      ForeColor: Navy\n  - name: lblHelp\n    type: Label\n    properties:\n      Caption: 폰에서 LiveQuiz를 열고 \"폰으로 참여\"를 고른 뒤 이 코드를 넣으세요.\n      Left: 16\n      Top: 40\n      Width: 440\n  - name: btnNext\n    type: Button\n    properties:\n      Caption: 시작\n      Left: 16\n      Top: 68\n      Width: 120\n  - name: lblTime\n    type: Label\n    properties:\n      Left: 152\n      Top: 74\n      Width: 304\n  - name: lblQuestion\n    type: Label\n    properties:\n      Left: 16\n      Top: 112\n      Width: 440\n  - name: lblChoices\n    type: Label\n    properties:\n      Left: 16\n      Top: 140\n      Width: 440\n      Height: 40\n  - name: imgQuestion\n    type: Image\n    properties:\n      Left: 480\n      Top: 176\n      Width: 144\n      Height: 96\n  - name: lstPlayers\n    type: ListBox\n    properties:\n      Left: 480\n      Top: 12\n      Width: 144\n      Height: 156\n  - name: lblFinish\n    type: Label\n    properties:\n      Caption: 결승선 ▶\n      Left: 400\n      Top: 188\n      Width: 72\n  - name: rmQuiz\n    type: Room\n    properties:\n      Nickname: TV\n  - name: tmrQuestion\n    type: Timer\n    properties:\n      Interval: 1000\n",
    "FormTV.gbas": "' TV 쪽: 방을 만들고, 들어온 사람마다 캐릭터를 하나씩 세우고, 문제를 냅니다.\n' 폰과는 JSON 글로 이야기합니다:\n'   TV → 모두  {\"kind\":\"question\",\"no\":1,\"text\":\"…\",\"choices\":[…],\"seconds\":15,\"host\":\"m1\"}\n'   폰 → TV    {\"kind\":\"answer\",\"no\":1,\"choice\":2}\n'   TV → 그 폰 {\"kind\":\"result\",\"no\":1,\"correct\":true,\"score\":10}\n'   TV → 모두  {\"kind\":\"score\",\"board\":[{\"member\":\"m2\",\"nickname\":\"민지\",\"score\":10}, …]}\n'   TV → 모두  {\"kind\":\"end\"}\n\nStructure Question\n    Text As String\n    Choices(3) As String\n    Answer As Integer       ' 정답 보기의 번호(0부터)\n    Picture As String       ' 그림 문제의 그림 이름, 없으면 \"\"\nEnd Structure\n\nStructure Player\n    Member As String        ' 방에서의 ID(m2, m3, …)\n    Nickname As String\n    Score As Integer\n    Answered As Boolean     ' 이번 문제에 답했는지\nEnd Structure\n\nConst Seconds As Integer = 15   ' 문제 하나에 주는 시간\nConst Finish As Integer = 400   ' 결승선의 Left\n\nDim questions(6) As Question\nDim players As New List(Of Player)\nDim runners As New List(Of Image)   ' players와 같은 순서\nDim current As Integer = -1         ' 지금 문제의 번호(0부터), 시작 전에는 -1\nDim secondsLeft As Integer\nDim rightSoFar As Integer           ' 이번 문제를 맞힌 사람 수\nDim asking As Boolean               ' 문제를 내고 답을 기다리는 중인지\n\nSub Form_Load()\n    questions(0) = New Question With {.Text = \"대한민국의 수도는 어디일까요?\",\n                                      .Choices = {\"부산\", \"서울\", \"대구\", \"인천\"}, .Answer = 1}\n    questions(1) = New Question With {.Text = \"윤년이 아닌 해는 며칠일까요?\",\n                                      .Choices = {\"360일\", \"365일\", \"366일\", \"370일\"}, .Answer = 1}\n    questions(2) = New Question With {.Text = \"1기압에서 물이 끓는 온도는?\",\n                                      .Choices = {\"50도\", \"80도\", \"100도\", \"120도\"}, .Answer = 2}\n    questions(3) = New Question With {.Text = \"세종대왕이 만든 글자는?\",\n                                      .Choices = {\"한자\", \"한글\", \"가나\", \"알파벳\"}, .Answer = 1}\n    questions(4) = New Question With {.Text = \"7 × 8은 얼마일까요?\",\n                                      .Choices = {\"54\", \"56\", \"58\", \"64\"}, .Answer = 1}\n    questions(5) = New Question With {.Text = \"이 도형의 이름은?\",\n                                      .Choices = {\"사각형\", \"원\", \"삼각형\", \"오각형\"}, .Answer = 2,\n                                      .Picture = \"triangle.png\"}\n    questions(6) = New Question With {.Text = \"이 도형의 꼭짓점은 몇 개일까요?\",\n                                      .Choices = {\"4개\", \"5개\", \"6개\", \"8개\"}, .Answer = 1,\n                                      .Picture = \"pentagon.png\"}\n    ' 방이 만들어질 때까지 기다리므로, 다음 줄에서 코드를 읽을 수 있습니다.\n    rmQuiz.Create()\n    lblCode.Caption = \"방 코드: \" & rmQuiz.Code\nEnd Sub\n\n' 누가 들어오면: 목록에 넣고, 달릴 캐릭터를 하나 세웁니다.\nSub rmQuiz_Joined(e As RoomEventArgs)\n    players.Add(New Player With {.Member = e.Member, .Nickname = e.Nickname})\n    Dim lane As Integer = (players.Count - 1) Mod 5\n    Dim runner As New Image\n    runner.Picture = \"runner\" & ((players.Count - 1) Mod 4 + 1) & \".png\"\n    runner.Width = 48\n    runner.Height = 48\n    runner.Left = 16\n    runner.Top = 212 + lane * 52\n    Me.Controls.Add(runner)\n    runners.Add(runner)\n    ShowPlayers()\nEnd Sub\n\n' 누가 나가면: 목록과 캐릭터를 치웁니다.\nSub rmQuiz_Left(e As RoomEventArgs)\n    Dim i As Integer = IndexOfMember(e.Member)\n    If i < 0 Then Exit Sub\n    Me.Controls.Remove(runners(i))\n    runners.RemoveAt(i)\n    players.RemoveAt(i)\n    ShowPlayers()\nEnd Sub\n\nSub btnNext_Click()\n    If current = -1 Then\n        ' 시작하면 더는 들어오지 못하게 방을 잠급니다.\n        rmQuiz.Lock()\n    End If\n    current = current + 1\n    rightSoFar = 0\n    For i As Integer = 0 To players.Count - 1\n        Dim p As Player = players(i)\n        p.Answered = False\n        players(i) = p\n    Next\n    Dim q As Question = questions(current)\n    lblQuestion.Caption = (current + 1) & \". \" & q.Text\n    lblChoices.Caption = \"1) \" & q.Choices(0) & \"   2) \" & q.Choices(1) & _\n                         \"   3) \" & q.Choices(2) & \"   4) \" & q.Choices(3)\n    imgQuestion.Picture = q.Picture\n    ' 문제를 모두에게 보냅니다. 폰은 \"host\"로 답을 보낼 곳을 압니다.\n    Dim message As New Json\n    message(\"kind\") = \"question\"\n    message(\"no\") = current + 1\n    message(\"text\") = q.Text\n    Dim choices As Json = Json.Array()\n    For Each c In q.Choices\n        choices.Add(c)\n    Next\n    message(\"choices\") = choices\n    message(\"seconds\") = Seconds\n    message(\"host\") = rmQuiz.Me\n    rmQuiz.Send(message.Text)\n    secondsLeft = Seconds\n    lblTime.Caption = \"남은 시간: \" & secondsLeft & \"초\"\n    asking = True\n    ' 답을 받는 동안에는 누를 수 없게 합니다.\n    btnNext.Enabled = False\n    tmrQuestion.Start()\nEnd Sub\n\nSub tmrQuestion_Tick()\n    secondsLeft = secondsLeft - 1\n    lblTime.Caption = \"남은 시간: \" & secondsLeft & \"초\"\n    If secondsLeft <= 0 Then EndQuestion()\nEnd Sub\n\n' 답이 오면: 맞았으면 빨리 맞힌 순서대로 10, 8, 6, 4, 그 뒤로는 3점.\nSub rmQuiz_Message(e As RoomEventArgs)\n    Dim m As Json = e.Json\n    If m(\"kind\").AsString <> \"answer\" Then Exit Sub\n    If Not asking Or m(\"no\").AsInteger <> current + 1 Then Exit Sub\n    Dim i As Integer = IndexOfMember(e.Member)\n    If i < 0 Then Exit Sub\n    Dim p As Player = players(i)\n    If p.Answered Then Exit Sub\n    p.Answered = True\n    Dim result As New Json\n    result(\"kind\") = \"result\"\n    result(\"no\") = current + 1\n    If m(\"choice\").AsInteger = questions(current).Answer Then\n        rightSoFar = rightSoFar + 1\n        Dim points As Integer = 12 - 2 * rightSoFar\n        If points < 3 Then points = 3\n        p.Score = p.Score + points\n        result(\"correct\") = True\n    Else\n        result(\"correct\") = False\n    End If\n    result(\"score\") = p.Score\n    players(i) = p\n    rmQuiz.SendTo(e.Member, result.Text)\n    ShowPlayers()\n    If EveryoneAnswered() Then EndQuestion()\nEnd Sub\n\nSub EndQuestion()\n    tmrQuestion.Stop()\n    asking = False\n    Dim q As Question = questions(current)\n    lblTime.Caption = \"정답: \" & (q.Answer + 1) & \") \" & q.Choices(q.Answer)\n    ' 순위표를 모두에게 보냅니다.\n    Dim board As Json = Json.Array()\n    For Each p In Ranked()\n        Dim row As New Json\n        row(\"member\") = p.Member\n        row(\"nickname\") = p.Nickname\n        row(\"score\") = p.Score\n        board.Add(row)\n    Next\n    Dim message As New Json\n    message(\"kind\") = \"score\"\n    message(\"board\") = board\n    rmQuiz.Send(message.Text)\n    If current = UBound(questions) Then\n        rmQuiz.Send(\"{\"\"kind\"\":\"\"end\"\"}\")\n        lblQuestion.Caption = \"끝! 1등: \" & Winner()\n        btnNext.Caption = \"끝\"\n    Else\n        btnNext.Caption = \"다음 문제\"\n        btnNext.Enabled = True\n    End If\nEnd Sub\n\nSub rmQuiz_Closed(e As RoomEventArgs)\n    tmrQuestion.Stop()\n    asking = False\n    lblCode.Caption = \"방이 끝났습니다(\" & e.Reason & \").\"\n    btnNext.Enabled = False\nEnd Sub\n\n' 목록에는 별명과 점수를, 캐릭터는 점수만큼 결승선 쪽으로.\nSub ShowPlayers()\n    lstPlayers.Clear()\n    Dim most As Integer = (UBound(questions) + 1) * 10\n    For i As Integer = 0 To players.Count - 1\n        Dim p As Player = players(i)\n        lstPlayers.AddItem(p.Nickname & \" \" & p.Score & \"점\")\n        runners(i).Left = 16 + (Finish - 16) * p.Score \\ most\n    Next\nEnd Sub\n\nFunction IndexOfMember(member As String) As Integer\n    For i As Integer = 0 To players.Count - 1\n        If players(i).Member = member Then Return i\n    Next\n    Return -1\nEnd Function\n\nFunction EveryoneAnswered() As Boolean\n    For Each p In players\n        If Not p.Answered Then Return False\n    Next\n    Return players.Count > 0\nEnd Function\n\n' 점수가 높은 순서로 늘어놓은 목록(같으면 먼저 들어온 사람이 앞).\nFunction Ranked() As List(Of Player)\n    Dim result As New List(Of Player)\n    For Each p In players\n        Dim at As Integer = result.Count\n        For i As Integer = 0 To result.Count - 1\n            If p.Score > result(i).Score Then\n                at = i\n                Exit For\n            End If\n        Next\n        result.Insert(at, p)\n    Next\n    Return result\nEnd Function\n\nFunction Winner() As String\n    Dim ranked As List(Of Player) = Ranked()\n    If ranked.Count = 0 Then Return \"없음\"\n    Return ranked(0).Nickname & \" (\" & ranked(0).Score & \"점)\"\nEnd Function\n",
    "LiveQuiz.gbproj": "formatVersion: 2\nname: LiveQuiz\nstartup: FormStart\nforms:\n  - FormStart\n  - FormTV\n  - FormPhone\npictures:\n  - triangle.png\n  - pentagon.png\n  - runner1.png\n  - runner2.png\n  - runner3.png\n  - runner4.png\n",
  },
  "notes": {
    "Form1.form.yaml": "formatVersion: 1\nproperties:\n  Caption: 메모장\n  Width: 420\n  Height: 320\ncontrols:\n  - name: txtNote\n    type: TextBox\n    properties:\n      Left: 16\n      Top: 16\n      Width: 284\n      Anchor: Left Top Right\n  - name: btnAdd\n    type: Button\n    properties:\n      Caption: 추가\n      Left: 308\n      Top: 16\n      Width: 96\n      Anchor: Top Right\n  - name: lstNotes\n    type: ListBox\n    properties:\n      Left: 16\n      Top: 56\n      Width: 388\n      Height: 180\n      Anchor: Left Top Right Bottom\n  - name: btnDelete\n    type: Button\n    properties:\n      Caption: 지우기\n      Left: 308\n      Top: 248\n      Width: 96\n      Anchor: Right Bottom\n  - name: lblCount\n    type: Label\n    properties:\n      Left: 16\n      Top: 254\n      Width: 284\n      Anchor: Left Right Bottom\n",
    "Form1.gbas": "' Notes kept in the app's own database (docs/DESIGN.md D126): every app\n' has an SQLite file of its own, data.db, that Database opens when first\n' used. Each note goes in with Database.Execute, the list is filled from\n' Database.Query, and a value always goes in for a ?, never joined into\n' the SQL, so that a quote in a note cannot break the statement. The notes\n' are still there the next time the program runs.\nDim notes As Table\n\nSub Form_Load()\n    Database.Execute(\"CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY, text TEXT NOT NULL, written TEXT NOT NULL)\")\n    ShowNotes()\nEnd Sub\n\nSub btnAdd_Click()\n    Dim text As String = txtNote.Text.Trim()\n    If text = \"\" Then Exit Sub\n    Database.Execute(\"INSERT INTO notes (text, written) VALUES (?, ?)\", text, Now)\n    txtNote.Text = \"\"\n    ShowNotes()\nEnd Sub\n\nSub btnDelete_Click()\n    If lstNotes.ListIndex < 0 Then Exit Sub\n    Database.Execute(\"DELETE FROM notes WHERE id = ?\", notes.Cell(lstNotes.ListIndex, \"id\"))\n    ShowNotes()\nEnd Sub\n\n' The notes, newest first, and how many there are.\nSub ShowNotes()\n    notes = Database.Query(\"SELECT id, text, written FROM notes ORDER BY id DESC\")\n    lstNotes.Clear()\n    For r = 0 To notes.RowCount - 1\n        lstNotes.AddItem(Left(notes.Cell(r, \"written\"), 16) & \"  \" & notes.Cell(r, \"text\"))\n    Next\n    lblCount.Caption = Database.Scalar(\"SELECT COUNT(*) FROM notes\") & \"개의 메모\"\nEnd Sub\n",
    "Notes.gbproj":
        "formatVersion: 1\nname: Notes\nstartup: Form1\nforms:\n  - Form1\n",
  },
  "quiz": {
    "Form1.form.yaml": "formatVersion: 1\nproperties:\n  Caption: 퀴즈\n  Width: 400\n  Height: 300\ncontrols:\n  - name: lblNumber\n    type: Label\n    properties:\n      Left: 16\n      Top: 12\n      Width: 368\n  - name: lblQuestion\n    type: Label\n    properties:\n      Left: 16\n      Top: 40\n      Width: 368\n  - name: lstChoices\n    type: ListBox\n    properties:\n      Left: 16\n      Top: 72\n      Width: 232\n      Height: 116\n  - name: imgQuestion\n    type: Image\n    properties:\n      Left: 264\n      Top: 72\n      Width: 120\n      Height: 116\n  - name: chkShowAnswer\n    type: CheckBox\n    properties:\n      Caption: 틀리면 정답 보여 주기\n      Left: 16\n      Top: 200\n      Width: 240\n  - name: btnCheck\n    type: Button\n    properties:\n      Caption: 정답 확인\n      Left: 16\n      Top: 248\n      Width: 136\n  - name: lblScore\n    type: Label\n    properties:\n      Left: 168\n      Top: 252\n      Width: 216\n",
    "Form1.gbas": "' 작은 퀴즈: 문제를 보여 주고, ListBox의 보기 가운데 하나를 고르면\n' 맞았는지 알려 주며 점수를 셉니다. 최고 점수는 저장해 두었다가 다음에\n' 실행할 때도 보여 줍니다. 그림 문제는 프로젝트의 그림(pictures 폴더)을\n' Image에 보여 줍니다.\n\n' 문제 하나에 딸린 것을 한 이름으로 묶습니다(Structure).\nStructure Question\n    Text As String\n    Choices(3) As String    ' 보기 네 개\n    Answer As Integer       ' 정답 보기의 번호(0부터)\n    Picture As String       ' 문제의 그림 이름. 그림이 없는 문제는 \"\"\nEnd Structure\n\nDim questions(6) As Question\nDim current As Integer\nDim score As Integer\nDim best As Integer\n\nSub Form_Load()\n    ' New … With { }로 문제 하나를 한 번에 만듭니다. 보기는 { }로 적은 배열입니다.\n    questions(0) = New Question With {.Text = \"대한민국의 수도는 어디일까요?\",\n                                      .Choices = {\"부산\", \"서울\", \"대구\", \"인천\"}, .Answer = 1}\n    questions(1) = New Question With {.Text = \"윤년이 아닌 해는 며칠일까요?\",\n                                      .Choices = {\"360일\", \"365일\", \"366일\", \"370일\"}, .Answer = 1}\n    questions(2) = New Question With {.Text = \"1기압에서 물이 끓는 온도는?\",\n                                      .Choices = {\"50도\", \"80도\", \"100도\", \"120도\"}, .Answer = 2}\n    questions(3) = New Question With {.Text = \"세종대왕이 만든 글자는?\",\n                                      .Choices = {\"한자\", \"한글\", \"가나\", \"알파벳\"}, .Answer = 1}\n    questions(4) = New Question With {.Text = \"7 × 8은 얼마일까요?\",\n                                      .Choices = {\"54\", \"56\", \"58\", \"64\"}, .Answer = 1}\n    questions(5) = New Question With {.Text = \"이 도형의 이름은?\",\n                                      .Choices = {\"사각형\", \"원\", \"삼각형\", \"오각형\"}, .Answer = 2,\n                                      .Picture = \"triangle.png\"}\n    questions(6) = New Question With {.Text = \"이 도형의 꼭짓점은 몇 개일까요?\",\n                                      .Choices = {\"4개\", \"5개\", \"6개\", \"8개\"}, .Answer = 1,\n                                      .Picture = \"pentagon.png\"}\n    ' 지난 실행까지의 최고 점수. 저장된 것이 없으면 \"0\"입니다.\n    best = CInt(GetSetting(\"best\", \"0\"))\n    ShowQuestion(0)\nEnd Sub\n\nSub ShowQuestion(number As Integer)\n    current = number\n    Dim q As Question = questions(number)\n    lblNumber.Caption = \"문제 \" & (number + 1) & \" / \" & (UBound(questions) + 1)\n    lblQuestion.Caption = q.Text\n    ' 그림 이름을 넣으면 그 그림을, \"\"을 넣으면 아무것도 보여 주지 않습니다.\n    imgQuestion.Picture = q.Picture\n    ' Clear()는 고른 항목도 지웁니다. 그래서 고른 것이 있었다면\n    ' lstChoices_Changed가 실행되고, ListIndex는 -1(고른 것 없음)이 됩니다.\n    lstChoices.Clear()\n    For Each choice In q.Choices\n        lstChoices.AddItem(choice)\n    Next\n    lblScore.Caption = \"점수: \" & score & \" · 최고 점수: \" & best\nEnd Sub\n\nSub lstChoices_Changed()\n    ' ListIndex가 바뀔 때마다 실행됩니다: 보기를 고를 때, 그리고 Clear()로\n    ' 고른 것이 없어질 때(ListIndex = -1).\n    If lstChoices.ListIndex = -1 Then\n        btnCheck.Caption = \"정답 확인\"\n    Else\n        btnCheck.Caption = \"확인: \" & lstChoices.Text\n    End If\nEnd Sub\n\nSub btnCheck_Click()\n    If lstChoices.ListIndex = -1 Then\n        MsgBox(\"먼저 보기를 하나 고르세요.\")\n        Exit Sub\n    End If\n    If lstChoices.ListIndex = questions(current).Answer Then\n        score = score + 1\n        MsgBox(\"정답입니다!\")\n    ElseIf chkShowAnswer.Checked Then\n        MsgBox(\"틀렸습니다. 정답: \" & lstChoices.List(questions(current).Answer))\n    Else\n        MsgBox(\"틀렸습니다.\")\n    End If\n    If current < UBound(questions) Then\n        ShowQuestion(current + 1)\n    Else\n        Dim message As String = (UBound(questions) + 1) & \"문제 가운데 \" & score & \"문제를 맞혔습니다.\"\n        If score > best Then\n            ' SaveSetting으로 저장한 값은 프로그램을 다시 실행해도 남습니다.\n            best = score\n            SaveSetting(\"best\", best)\n            message = message & \" 새 최고 점수입니다!\"\n        End If\n        MsgBox(message & \" 처음부터 다시 합니다.\")\n        score = 0\n        ShowQuestion(0)\n    End If\nEnd Sub\n",
    "Quiz.gbproj": "formatVersion: 2\nname: Quiz\nstartup: Form1\nforms:\n  - Form1\npictures:\n  - triangle.png\n  - pentagon.png\n",
  },
  "scores": {
    "Form1.form.yaml": "formatVersion: 1\nproperties:\n  Caption: 성적표\n  Width: 480\n  Height: 340\ncontrols:\n  - name: grdScores\n    type: Grid\n    properties:\n      Left: 16\n      Top: 16\n      Width: 448\n      Height: 220\n      Anchor: Left Top Right Bottom\n  - name: lblTotal\n    type: Label\n    properties:\n      Left: 16\n      Top: 248\n      Width: 448\n      Anchor: Left Right Bottom\n  - name: btnOpen\n    type: Button\n    properties:\n      Caption: CSV 열기\n      Left: 16\n      Top: 288\n      Width: 120\n      Anchor: Left Bottom\n  - name: btnPdf\n    type: Button\n    properties:\n      Caption: PDF로 저장\n      Left: 144\n      Top: 288\n      Width: 120\n      Anchor: Left Bottom\n  - name: lblStatus\n    type: Label\n    properties:\n      Left: 280\n      Top: 294\n      Width: 184\n      Anchor: Left Right Bottom\n  - name: dlgOpen\n    type: OpenFileDialog\n    properties:\n      Title: 명단 열기\n      Filter: CSV 파일|*.csv\n  - name: dlgSave\n    type: SaveFileDialog\n    properties:\n      Title: 성적 저장\n      Filter: PDF 파일|*.pdf\n      FileName: 성적.pdf\n",
    "Form1.gbas": "' Work automation (docs/DESIGN.md D117): a list in a Grid, its total and\n' average, saved as a PDF file. It starts with three names; CSV 열기\n' (Open CSV) reads your own list, a CSV file with a column named 점수\n' (score), such as one Excel saves. Change a score in the Grid and the\n' total follows. A list of more than four columns is saved on pages\n' turned on their side.\nSub Form_Load()\n    grdScores.AddColumn(\"이름\")\n    grdScores.AddColumn(\"반\")\n    grdScores.AddColumn(\"점수\")\n    AddStudent(\"김하나\", \"1반\", 90)\n    AddStudent(\"박둘\", \"2반\", 85)\n    AddStudent(\"이셋\", \"1반\", 70)\n    ShowTotal()\nEnd Sub\n\nSub AddStudent(name As String, group As String, score As Integer)\n    Dim r As Integer = grdScores.AddRow()\n    grdScores.Cell(r, \"이름\") = name\n    grdScores.Cell(r, \"반\") = group\n    grdScores.Cell(r, \"점수\") = score\nEnd Sub\n\nSub ShowTotal()\n    If grdScores.Column(\"점수\") < 0 Then\n        lblTotal.Caption = \"점수 열이 없는 명단입니다.\"\n    ElseIf grdScores.RowCount = 0 Then\n        lblTotal.Caption = \"명단이 비어 있습니다.\"\n    Else\n        Dim total As Double = 0\n        For i As Integer = 0 To grdScores.RowCount - 1\n            total = total + Val(grdScores.Cell(i, \"점수\"))\n        Next\n        Dim average As String = Format(total / grdScores.RowCount, \"0.0\")\n        lblTotal.Caption = grdScores.RowCount & \"명, 합계 \" & total & \", 평균 \" & average\n    End If\nEnd Sub\n\nSub grdScores_Changed()\n    ShowTotal()\nEnd Sub\n\nSub btnOpen_Click()\n    If dlgOpen.ShowDialog() = DialogResult.OK Then\n        grdScores.LoadCsv(dlgOpen.FileName)\n        ShowTotal()\n    End If\nEnd Sub\n\nSub btnPdf_Click()\n    If dlgSave.ShowDialog() = DialogResult.OK Then\n        Dim pdf As New PdfDocument\n        pdf.TitleSize = 20\n        If grdScores.ColumnCount > 4 Then\n            pdf.Landscape = True\n        End If\n        pdf.AddTitle(\"성적표\")\n        pdf.AddText(lblTotal.Caption)\n        pdf.AddTable(grdScores)\n        pdf.Save(dlgSave.FileName)\n        lblStatus.Caption = \"저장했습니다: \" & dlgSave.FileName\n    End If\nEnd Sub\n",
    "Scores.gbproj":
        "formatVersion: 1\nname: Scores\nstartup: Form1\nforms:\n  - Form1\n",
  },
  "typing": {
    "Form1.form.yaml": "formatVersion: 1\nproperties:\n  Caption: Typing\n  Width: 320\n  Height: 160\ncontrols:\n  - name: txtName\n    type: TextBox\n    properties:\n      Left: 16\n      Top: 16\n      Width: 288\n  - name: lblMessage\n    type: Label\n    properties:\n      Left: 16\n      Top: 60\n      Width: 288\n  - name: btnHello\n    type: Button\n    properties:\n      Caption: Say hello\n      Left: 16\n      Top: 100\n      Width: 120\n",
    "Form1.gbas": "' Typing in a TextBox: Changed runs each time the input method commits\n' a character (docs/LANGUAGE.md §11.1). Try it with a Korean input method.\nDim clickCount As Integer\n\nSub Form_Load()\n    lblMessage.Caption = \"Type your name, or press the button\"\nEnd Sub\n\nSub txtName_Changed()\n    lblMessage.Caption = \"Hello, \" & txtName.Text\nEnd Sub\n\nSub btnHello_Click()\n    clickCount = clickCount + 1\n    Dim name = txtName.Text\n    If name = \"\" Then\n        name = InputBox(\"What is your name?\")\n    End If\n    MsgBox(\"Hello, \" & name & \"! (\" & clickCount & \")\")\nEnd Sub\n",
    "Typing.gbproj":
        "formatVersion: 1\nname: Typing\nstartup: Form1\nforms:\n  - Form1\n",
  },
  "weather": {
    "Form1.form.yaml": "formatVersion: 1\nproperties:\n  Caption: 지금 날씨\n  Width: 360\n  Height: 220\ncontrols:\n  - name: lblCity\n    type: Label\n    properties:\n      Caption: 도시\n      Left: 16\n      Top: 20\n      Width: 48\n  - name: cboCity\n    type: ComboBox\n    properties:\n      Left: 64\n      Top: 16\n      Width: 160\n  - name: btnWeather\n    type: Button\n    properties:\n      Caption: 날씨 보기\n      Left: 240\n      Top: 16\n      Width: 104\n  - name: lblTemp\n    type: Label\n    properties:\n      Left: 16\n      Top: 64\n      Width: 328\n      Height: 32\n  - name: lblSky\n    type: Label\n    properties:\n      Left: 16\n      Top: 104\n      Width: 328\n  - name: lblWind\n    type: Label\n    properties:\n      Left: 16\n      Top: 136\n      Width: 328\n  - name: lblStatus\n    type: Label\n    properties:\n      Left: 16\n      Top: 176\n      Width: 328\n      Anchor: Left Top Right\n",
    "Form1.gbas": "' The weather now (docs/DESIGN.md D125): Http.GetJson asks Open-Meteo, a\n' free weather service that needs no key (https://open-meteo.com/), and\n' the answer's JSON is read member by member. The program waits where it\n' asks; the pointer shows waiting meanwhile. An answer that does not\n' come, or is not what was expected, is caught and shown.\nSub Form_Load()\n    cboCity.AddItem(\"서울\")\n    cboCity.AddItem(\"부산\")\n    cboCity.AddItem(\"제주\")\n    cboCity.ListIndex = 0\n    lblStatus.Caption = \"도시를 고르고 날씨 보기를 누르세요.\"\nEnd Sub\n\nSub btnWeather_Click()\n    Dim latitude As String = \"37.57\"\n    Dim longitude As String = \"126.98\"\n    Select Case cboCity.Text\n        Case \"부산\"\n            latitude = \"35.18\"\n            longitude = \"129.08\"\n        Case \"제주\"\n            latitude = \"33.50\"\n            longitude = \"126.53\"\n    End Select\n    Dim url As String = \"https://api.open-meteo.com/v1/forecast?latitude=\" & latitude & \"&longitude=\" & longitude & \"&current=temperature_2m,wind_speed_10m,weather_code&timezone=Asia%2FSeoul\"\n    lblStatus.Caption = \"가져오는 중…\"\n    Try\n        Dim reply As Json = Http.GetJson(url)\n        Dim now As Json = reply(\"current\")\n        Dim units As Json = reply(\"current_units\")\n        lblTemp.Caption = cboCity.Text & \" \" & now(\"temperature_2m\").AsDouble & units(\"temperature_2m\").AsString\n        lblSky.Caption = SkyOf(now(\"weather_code\").AsInteger)\n        lblWind.Caption = \"바람 \" & now(\"wind_speed_10m\").AsDouble & \" \" & units(\"wind_speed_10m\").AsString\n        lblStatus.Caption = now(\"time\").AsString & \" 기준\"\n    Catch ex As Exception\n        lblStatus.Caption = ex.Message\n    End Try\nEnd Sub\n\n' The sky from a WMO weather code, as Open-Meteo gives it.\nFunction SkyOf(code As Integer) As String\n    Select Case code\n        Case 0\n            Return \"맑음\"\n        Case 1, 2, 3\n            Return \"구름 조금에서 흐림\"\n        Case 45, 48\n            Return \"안개\"\n        Case 51 To 67\n            Return \"비\"\n        Case 71 To 77\n            Return \"눈\"\n        Case 80 To 82\n            Return \"소나기\"\n        Case 95 To 99\n            Return \"뇌우\"\n    End Select\n    Return \"날씨 코드 \" & code\nEnd Function\n",
    "Weather.gbproj":
        "formatVersion: 1\nname: Weather\nstartup: Form1\nforms:\n  - Form1\n",
  },
};

